+
+    form {
+      display: grid;
+      gap: 1.5rem;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 1rem;
+      margin: 0;
+      border: 0;
+      padding: 0;
+    }
+
+    legend {
+      margin: 0;
+      padding: 0;
+      color: var(--text);
+      font-size: 1.2rem;
+      font-weight: 800;
