+      border-color: var(--primary);
+      background: var(--primary-soft);
+    }
+
+    .radio-option input {
+      width: 1.25rem;
+      height: 1.25rem;
+      margin: 0;
+      accent-color: var(--primary);
+    }
+
+    .radio-option input:focus-visible {
+      outline: 3px solid var(--primary);
+      outline-offset: 3px;
+    }
+
+    .option-text {
+      min-width: 0;
+      color: var(--text);
+      font-weight: 750;
+      overflow-wrap: anywhere;
+    }
+
+    .submit-button {
+      justify-self: start;
+      min-height: 3rem;
+      border: 0;
+      border-radius: 999px;
+      padding: 0.85rem 1.35rem;
+      color: #ffffff;
+      background: var(--primary);
+      font: inherit;
+      font-weight: 800;
+      cursor: pointer;
+      box-shadow: 0 12px 30px rgba(31, 94, 255, 0.28);
+    }
+
+    .submit-button:hover {
+      background: var(--primary-strong);
+    }
+
+    .submit-button:focus-visible {
+      outline: 3px solid #0d1b2f;
+      outline-offset: 4px;
+    }
+
+    .status {
+      min-height: 1.5rem;
+      margin: 0;
+      color: var(--muted);
+      font-weight: 700;
+    }
+
+    @media (max-width: 26rem) {
+      .card {
+        border-radius: 18px;
+      }
+
+      .radio-option {
+        padding: 0.9rem;
+      }
+    }
+
+    @media (prefers-reduced-motion: reduce) {
+      *,
+      *::before,
+      *::after {
+        scroll-behavior: auto !important;
+        transition-duration: 0.01ms !important;
+        animation-duration: 0.01ms !important;
+        animation-iteration-count: 1 !important;
+      }
