      --page: #f6f8fb;
      --surface: #ffffff;
      --text: #172033;
      --muted: #5d6b82;
      --border: #c8d1df;
      --border-strong: #7687a0;
      --primary: #1f5eff;
      --primary-strong: #1647c7;
      --primary-soft: #edf3ff;
      --shadow: 0 24px 70px rgba(23, 32, 51, 0.14);
      --radius: 24px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
