      font-weight: 800;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      color: var(--text);
      font-size: clamp(2rem, 7vw, 3.25rem);
      line-height: 1;
      letter-spacing: -0.055em;
    }

