      border-radius: 999px;
      padding: 0.85rem 1.35rem;
      color: #ffffff;
      background: var(--primary);
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 12px 30px rgba(31, 94, 255, 0.28);
