    .submit-button:hover {
      background: var(--primary-strong);
    }

    .submit-button:focus-visible {
      outline: 3px solid #0d1b2f;
      outline-offset: 4px;
    }

    .status {
      min-height: 1.5rem;
      margin: 0;
      color: var(--muted);
      font-weight: 700;
    }

    @media (max-width: 26rem) {
      .card {
        border-radius: 18px;
      }

      .radio-option {
        padding: 0.9rem;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
