    h1 {
      margin: 0;
      color: var(--text);
      font-size: clamp(2rem, 7vw, 3.25rem);
      line-height: 1;
      letter-spacing: -0.055em;
    }

    .intro {
      max-width: 34rem;
      margin: 1rem 0 2rem;
      color: var(--muted);
      font-size: 1.06rem;
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 1.5rem;
    }

    .form-field {
      display: grid;
      gap: 1rem;
      margin: 0;
      border: 0;
      padding: 0;
    }

    legend {
      margin: 0;
      padding: 0;
      color: var(--text);
      font-size: 1.2rem;
      font-weight: 800;
    }

    .required-note {
      color: var(--muted);
      font-size: 0.95rem;
      font-weight: 500;
    }

    .radio-group {
      display: grid;
      gap: 0.8rem;
    }

    .radio-option {
      display: grid;
      grid-template-columns: auto 1fr;
      gap: 0.85rem;
      align-items: center;
      min-width: 0;
      border: 1px solid var(--border);
      border-radius: 18px;
      padding: 1rem;
      background: var(--surface);
      cursor: pointer;
      transition: border-color 160ms ease, background-color 160ms ease, transform 160ms ease;
    }

    .radio-option:hover {
      border-color: var(--border-strong);
      background: #fbfdff;
      transform: translateY(-1px);
    }

    .radio-option:has(input:checked) {
      border-color: var(--primary);
      background: var(--primary-soft);
    }

    .radio-option input {
      width: 1.25rem;
      height: 1.25rem;
      margin: 0;
      accent-color: var(--primary);
