        border-color: Highlight;
      }

      .submit-button {
        color: ButtonText;
        background: ButtonFace;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="root"></div>

  <script>
    const notificationOptions = ["Email", "SMS", "Push Notifications"];

    function RadioOption({ id, name, value, required }) {
      return `
        <label class="radio-option" for="${id}">
          <input id="${id}" type="radio" name="${name}" value="${value}" ${required ? "required" : ""}>
          <span class="option-text">${value}</span>
        </label>
      `;
    }

    function NotificationForm() {
      const radioOptions = notificationOptions
        .map((option, index) => RadioOption({
          id: `notification-${index}`,
          name: "notificationPreference",
          value: option,
          required: index === 0
        }))
        .join("");

      return `
        <form id="notification-form" novalidate>
          <fieldset class="form-field">
            <legend>
              How do you prefer to receive notifications?
              <span class="required-note">(required)</span>
            </legend>
            <div class="radio-group">
              ${radioOptions}
            </div>
          </fieldset>
          <button class="submit-button" type="submit">Submit preference</button>
          <p class="status" id="form-status" aria-live="polite"></p>
        </form>
      `;
    }

    function App() {
      return `
        <main id="main-content" class="page-shell">
          <section class="card" aria-labelledby="page-title">
            <p class="eyebrow">Account settings</p>
            <h1 id="page-title">Notification preferences</h1>
            <p class="intro">Choose the channel that works best for timely product updates and account messages.</p>
            ${NotificationForm()}
          </section>
        </main>
      `;
    }

    document.getElementById("root").innerHTML = App();

    document.getElementById("notification-form").addEventListener("submit", (event) => {
      event.preventDefault();

      const form = event.currentTarget;
      const status = document.getElementById("form-status");
      const selectedOption = form.querySelector("input[name='notificationPreference']:checked");

      if (!selectedOption) {
        status.textContent = "Choose one notification method before submitting.";
        form.querySelector("input[name='notificationPreference']").focus();
        return;
      }

      status.textContent = `Preference saved: ${selectedOption.value}.`;
    });
  </script>
</body>
</html>
